<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router } from '@inertiajs/vue3';
const props = defineProps<{ importBatch: any; rows: { data: any[] }; canCommit: boolean }>();
const commit = () => { if (confirm(`Créer ${props.importBatch.valid_rows} ouvrage(s) et leurs exemplaires ?`)) router.post(route('book-imports.commit', props.importBatch.id)); };
</script>
<template><Head title="Contrôle import ouvrages"/><AuthenticatedLayout><template #header><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><Link :href="route('book-imports.index')" class="text-xs font-bold text-primary-600 hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300">← Imports</Link><h1 class="dw-page-title mt-2">Contrôle des ouvrages</h1><p class="dw-page-description">{{importBatch.original_filename}} · {{importBatch.sheet_name}}</p></div><button v-if="canCommit&&['ready','needs_review'].includes(importBatch.status)&&importBatch.valid_rows" class="dw-btn-primary" @click="commit">Valider les lignes correctes</button></div></template><div v-if="$page.props.flash?.success" class="mb-5 rounded-md bg-emerald-50 p-4 text-sm font-semibold text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300">{{$page.props.flash.success}}</div><div class="mb-6 grid gap-4 sm:grid-cols-4"><div v-for="metric in [{l:'Ouvrages',v:importBatch.total_rows},{l:'Valides',v:importBatch.valid_rows},{l:'À corriger',v:importBatch.error_rows},{l:'Importés',v:importBatch.imported_rows}]" :key="metric.l" class="dw-card p-4"><p class="text-xs text-slate-500 dark:text-slate-400">{{metric.l}}</p><strong class="mt-1 block text-xl text-slate-800">{{metric.v}}</strong></div></div><section class="dw-card overflow-x-auto"><table class="dw-table min-w-[1050px] text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:text-slate-400"><tr><th class="p-4">Ligne</th><th class="p-4 text-start">Catégorie</th><th class="p-4 text-start">Titre</th><th class="p-4 text-start">Auteur(s)</th><th class="p-4">Qté</th><th class="p-4 text-start">Résultat</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="row in rows.data" :key="row.id"><td class="p-4 text-center font-mono">{{row.row_number}}</td><td class="p-4">{{row.normalized_data.category||'—'}}</td><td class="p-4 font-semibold text-slate-700">{{row.normalized_data.title}}</td><td class="p-4 text-xs">{{row.normalized_data.authors.join(', ')||'—'}}</td><td class="p-4 text-center font-bold">{{row.normalized_data.quantity??'?'}}</td><td class="p-4"><span v-if="row.status==='valid'" class="text-xs font-bold text-emerald-600">Valide</span><span v-else-if="row.status==='imported'" class="text-xs font-bold text-primary-600 hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300">Importé</span><ul v-else class="list-disc ps-4 text-xs text-red-600"><li v-for="error in row.errors" :key="error">{{error}}</li></ul></td></tr></tbody></table></section></AuthenticatedLayout></template>
